const s=ctx.state,gl=ctx.gl;s.n=64;if(!gl.getExtension('EXT_color_buffer_float'))throw Error('This example requires float color buffers.');
s.source=await(await fetch(ctx.assets['fft.glsl'])).text();s.compute=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,'#version 300 es\nprecision highp float;\n#define texture2D texture\n'+s.source.replace(/#pragma glslify: export\(fft\)/,'')+'\nuniform sampler2D u_src;uniform float u_size,u_norm;uniform bool u_horizontal,u_forward;out vec4 result;void main(){result=fft(u_src,vec2(1./64.),u_size,u_horizontal,u_forward,u_norm);}');
s.buffers=Array.from({length:4},()=>{const texture=gl.createTexture();gl.bindTexture(gl.TEXTURE_2D,texture);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA32F,64,64,0,gl.RGBA,gl.FLOAT,null);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.NEAREST);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.NEAREST);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);const fbo=gl.createFramebuffer();gl.bindFramebuffer(gl.FRAMEBUFFER,fbo);gl.framebufferTexture2D(gl.FRAMEBUFFER,gl.COLOR_ATTACHMENT0,gl.TEXTURE_2D,texture,0);if(gl.checkFramebufferStatus(gl.FRAMEBUFFER)!==gl.FRAMEBUFFER_COMPLETE)throw Error('Incomplete float target');return {texture,fbo};});
s.transform=(input,forward)=>{let src=input;for(let axis=0;axis<2;axis++)for(let size=2;size<=64;size*=2){const target=src===1?2:1;gl.bindFramebuffer(gl.FRAMEBUFFER,s.buffers[target].fbo);gl.viewport(0,0,64,64);gl.useProgram(s.compute);ctx.utils.bindTexture(s.compute,'u_src',s.buffers[src].texture,0);gl.uniform1f(gl.getUniformLocation(s.compute,'u_size'),size);gl.uniform1f(gl.getUniformLocation(s.compute,'u_norm'),forward?1:.5);gl.uniform1i(gl.getUniformLocation(s.compute,'u_horizontal'),axis===0?1:0);gl.uniform1i(gl.getUniformLocation(s.compute,'u_forward'),forward?1:0);ctx.utils.drawFullscreen(s.compute);src=target;}return src;};
s.show=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,`#version 300 es
precision highp float;in vec2 v_uv;out vec4 color;uniform sampler2D u_input,u_spectrum;void main(){vec2 p=v_uv;bool right=p.x>.5;p.x=fract(p.x*2.);vec3 c;if(right){vec2 q=fract(p+.5);vec2 z=texture(u_spectrum,q).xy;float a=clamp(log(1.+length(z))/8.,0.,1.);c=mix(vec3(.035,.065,.10),vec3(1.,.62,.3),a);}else{float a=.5+.5*texture(u_input,p).x;c=mix(vec3(.035,.065,.10),vec3(.28,.84,.78),a);}if(abs(v_uv.x-.5)<.002)c=vec3(.5);color=vec4(c,1.);}`);gl.bindFramebuffer(gl.FRAMEBUFFER,null);
